	@Test
	void costingTraceDetachesCompleteReplayContext() throws Exception {
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		TupleExpr source = connectedJoin("left", "right");
		PackedPlanCache.Context context = context(11L);
		PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), cache, context, frontierCostModel());
		PackedPlanCache.PlanEntry entry = cache.findPlan(cache.fingerprint(source), context, source);
		PackedCostingTrace trace = entry.recipe().costingTrace();
		Method relationId = PackedCostingTrace.class.getDeclaredMethod("relationId", int.class);
		Method inputStateOrdinal = PackedCostingTrace.class.getDeclaredMethod("inputStateOrdinal", int.class);
		Method outputStateOrdinal = PackedCostingTrace.class.getDeclaredMethod("outputStateOrdinal", int.class);
		Method prefixRelationCount = PackedCostingTrace.class.getDeclaredMethod("prefixRelationCount", int.class);
		Method prefixRelationId = PackedCostingTrace.class.getDeclaredMethod(
				"prefixRelationId", int.class, int.class);
		Method prefixRows = PackedCostingTrace.class.getDeclaredMethod("prefixRows", int.class);
		Method assuredBindingRelationId = PackedCostingTrace.class.getDeclaredMethod(
				"assuredBindingRelationId", int.class);
		Method bindingLayoutId = PackedCostingTrace.class.getDeclaredMethod("bindingLayoutId", int.class);
		Method correlationMaskId = PackedCostingTrace.class.getDeclaredMethod("correlationMaskId", int.class);
		Method semanticScopeMaskId = PackedCostingTrace.class.getDeclaredMethod("semanticScopeMaskId", int.class);

		int extensionEvent = 0;
		for (int eventId = 1; eventId <= trace.eventCount(); eventId++) {
			if (trace.phase(eventId) == PackedCostingPhase.PREFIX_EXTENSION) {
				extensionEvent = eventId;
				break;
			}
		}
		assertTrue(extensionEvent > 0);
		assertTrue((int) relationId.invoke(trace, extensionEvent) > 0);
		assertTrue((int) inputStateOrdinal.invoke(trace, extensionEvent) > 0);
		assertTrue((int) outputStateOrdinal.invoke(trace, extensionEvent) > 0);
		assertTrue((int) outputStateOrdinal.invoke(trace, extensionEvent) <= entry.recipe()
				.frontierEvidenceBundle()
				.stateCount());
		assertEquals(1, prefixRelationCount.invoke(trace, extensionEvent));
		assertTrue((int) prefixRelationId.invoke(trace, extensionEvent, 0) > 0);
		assertEquals(1.0d, (double) prefixRows.invoke(trace, extensionEvent));
		assertEquals(0, assuredBindingRelationId.invoke(trace, extensionEvent));
		assertEquals(0, bindingLayoutId.invoke(trace, extensionEvent));
		assertEquals(0, correlationMaskId.invoke(trace, extensionEvent));
		assertEquals(0, semanticScopeMaskId.invoke(trace, extensionEvent));
	}

	@Test
	void cachedRecipeRetainsOnlyDecisionReachableCostingEvents() {
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		TupleExpr source = connectedJoin("left", "right");
		PackedPlanCache.Context context = context(11L);
		PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), cache, context, frontierCostModel());
		PackedPlanRecipe recipe = cache.findPlan(cache.fingerprint(source), context, source).recipe();
		PackedCostingTrace trace = recipe.costingTrace();
		PackedDecisionCertificate certificate = recipe.decisionCertificate();
		boolean[] reachable = new boolean[trace.eventCount() + 1];

		for (int recipeId = 1; recipeId <= recipe.size(); recipeId++) {
			markEvent(reachable, recipe.costEventId(recipeId));
		}
		for (int candidate = 0; candidate < certificate.candidateCount(); candidate++) {
			markEvent(reachable, certificate.candidateEventId(candidate));
			for (int child = 0; child < certificate.candidateChildCount(candidate); child++) {
				markEvent(reachable, certificate.candidateChildEventId(candidate, child));
			}
		}
		for (int eventId = trace.eventCount(); eventId > 0; eventId--) {
			if (reachable[eventId]) {
				markEvent(reachable, trace.providerInputCostEventId(eventId));
			}
		}

		int reachableCount = 0;
		for (int eventId = 1; eventId < reachable.length; eventId++) {
			reachableCount += reachable[eventId] ? 1 : 0;
		}
		assertEquals(reachableCount, trace.eventCount(),
				"a cached recipe must not copy costing events which cannot affect its plan or decision proof");
	}

	private static void markEvent(boolean[] reachable, int eventId) {
		if (eventId > 0) {
			assertTrue(eventId < reachable.length, () -> "costing event " + eventId + " is outside the trace");
			reachable[eventId] = true;
		}
	}

