		assertTrue(refinementEvent > 0, "at least one operator refinement must retain its provider input");
		assertTrue((double) providerInputRows.invoke(trace, refinementEvent) >= 0.0d);
		assertTrue((double) providerInputWorkRows.invoke(trace, refinementEvent) >= 0.0d);
