	@Test
	void lowConfidenceCertifiedReuseRunsAnIndependentShadowReplan() {
		AtomicInteger sessions = new AtomicInteger();
		AtomicInteger validations = new AtomicInteger();
		AtomicInteger audits = new AtomicInteger();
		AtomicInteger auditLane = new AtomicInteger(-1);
		PackedCostModel frontier = frontierCostModel();
		Object proxy = Proxy.newProxyInstance(getClass().getClassLoader(),
				new Class<?>[] { PackedCostModel.class, PackedStalePlanValidator.class },
				(ignored, method, arguments) -> {
					return switch (method.getName()) {
					case "estimateRows" -> 1.0d;
					case "openSession" -> {
						sessions.incrementAndGet();
						yield frontier.openSession((PackedQueryView) arguments[0]);
					}
					case "validateStalePlan" -> {
						validations.incrementAndGet();
						PackedPlanValidationRequest request = (PackedPlanValidationRequest) arguments[0];
						yield PackedStalePlanValidation.certified(request.evidenceBundle(),
								request.candidateCostsCopy(), 0.51d, 0.005d, 1L,
								"low-confidence-certified-reuse");
					}
					case "recordStalePlanAudit" -> {
						PackedStalePlanAudit audit = (PackedStalePlanAudit) arguments[0];
						audits.incrementAndGet();
						auditLane.set(audit.auditLane());
						yield null;
					}
					case "toString" -> "frontier-shadow-auditing-test-model";
					default -> throw new AssertionError("unexpected shadow-auditing-model call " + method);
					};
				});
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		TupleExpr source = connectedJoin("left", "right");
		PackedPlanCache.Context original = context(11L);
		PackedPlanCache.Context revised = context(16L);

		PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), cache, original, (PackedCostModel) proxy);
		PackedPlanningResult audited = PackedCascadesPlanner.optimize(
				source, OptimizationGoal.root(), cache, revised, (PackedCostModel) proxy);

		assertEquals(2, sessions.get(), "the certified stale plan must be independently shadow-replanned");
		assertEquals(1, validations.get());
		assertEquals(1, audits.get());
		assertTrue(auditLane.get() > 0, "a shadow replan must be assigned an independent deterministic audit lane");
		assertFalse(audited.metrics().planCacheHit(), "an audited invocation returns the independently planned result");
		assertEquals("shadow-audit",
				audited.selectedPlan().getStringMetricPlanned("optimizer.planCacheValidationResult"));
	}

