	private static PackedCostModel multiplyingFrontierCostModel() {
		return new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return relationId + 1.0d;
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {
					private final FrontierStateArena arena = new FrontierStateArena(256L * 1024L);

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						publish(output, relationId + 1.0d, false);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						publish(output, context.prefixRows() * 2.0d, true);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
						double rows = Double.isFinite(output.outputRows()) ? output.outputRows()
								: context.leftInputRows();
						publish(output, rows, output.hasContextualOutputRows());
					}

					@Override
					public FrontierEvidenceBundle detachEvidence(int[] evidenceStateIds) {
						return arena.exportEvidence(evidenceStateIds);
					}

					@Override
					public void close() {
						arena.close();
					}

					private void publish(PackedCostEstimate output, double rows, boolean contextual) {
						if (contextual) {
							output.setContextualRows(rows, rows);
						} else {
							output.setRows(rows, rows);
						}
						EvidenceStateRef state = arena.append(
								FrontierLayout.of("subject", "predicate", "object"), EvidenceStateSummary.exact(rows));
						output.setEvidenceStateId(state.stateId());
						output.setEvidenceGuarantee(state.summary().guarantee());
						output.setEvidenceDisposition(FrontierStateDisposition.COMPOSABLE_PAYLOAD);
					}
				};
			}
		};
	}

	private static PackedCostModel demandRealizedFrontierCostModel(AtomicInteger realizations) {
		return new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return relationId + 1.0d;
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {
					private final FrontierStateArena arena = new FrontierStateArena(64L * 1024L);
					private final EvidenceStateRef descriptor = arena.append(
							FrontierLayout.of("subject"), EvidenceStateSummary.exact(2.0d));
					private final EvidenceStateRef canonical = arena.append(
							FrontierLayout.of("subject"), EvidenceStateSummary.exact(2.0d));

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						output.setRows(relationId + 1.0d, relationId + 1.0d);
						output.setEvidenceStateId(descriptor.stateId());
						output.setEvidenceGuarantee(descriptor.summary().guarantee());
						output.setEvidenceDisposition(FrontierStateDisposition.BOUND_ONLY);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						assertEquals(canonical.stateId(), context.evidenceStateId());
						output.setContextualRows(context.prefixRows() * 2.0d, context.prefixRows() * 2.0d);
						output.setEvidenceStateId(canonical.stateId());
						output.setEvidenceGuarantee(canonical.summary().guarantee());
						output.setEvidenceDisposition(FrontierStateDisposition.COMPOSABLE_PAYLOAD);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
					}

					@Override
					public int realizeEvidenceState(int evidenceStateId) {
						if (evidenceStateId == descriptor.stateId()) {
							realizations.incrementAndGet();
							return canonical.stateId();
						}
						return evidenceStateId;
					}

					@Override
					public void realizeEvidenceState(PackedCostEstimate evidence) {
						if (evidence.evidenceStateId() == descriptor.stateId()) {
							realizations.incrementAndGet();
							evidence.setEvidenceStateId(canonical.stateId());
							evidence.setEvidenceGuarantee(canonical.summary().guarantee());
							evidence.setEvidenceDisposition(FrontierStateDisposition.COMPOSABLE_PAYLOAD);
						}
					}

					@Override
					public FrontierEvidenceBundle detachEvidence(int[] evidenceStateIds) {
						return arena.exportEvidence(evidenceStateIds);
					}

					@Override
					public void close() {
						arena.close();
					}
				};
			}
		};
	}

	private static PackedCostSession replaySession(double workRows, AtomicInteger contextualCalls,
			AtomicInteger refinementInputs) {
		return new PackedCostSession() {
			private final FrontierStateArena arena = new FrontierStateArena(64L * 1024L);
			private final EvidenceStateRef state = arena.append(
					FrontierLayout.of("subject", "predicate", "object"), EvidenceStateSummary.exact(1.0d));

			@Override
			public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
				publish(output);
			}

			@Override
			public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
				assertTrue(context.evidenceStateId() > 0);
				assertTrue(context.prefixRelationCount() > 0);
				contextualCalls.incrementAndGet();
				publish(output);
			}

			@Override
			public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
				if (Double.isFinite(output.outputRows()) && Double.isFinite(output.workRows())) {
					refinementInputs.incrementAndGet();
				}
				publish(output);
			}

			@Override
			public FrontierEvidenceBundle detachEvidence(int[] evidenceStateIds) {
				return arena.exportEvidence(evidenceStateIds);
			}

			@Override
			public void close() {
				arena.close();
			}

			private void publish(PackedCostEstimate output) {
				output.setRows(1.0d, workRows);
				output.setEvidenceStateId(state.stateId());
				output.setEvidenceGuarantee(state.summary().guarantee());
				output.setEvidenceDisposition(FrontierStateDisposition.COMPOSABLE_PAYLOAD);
			}
		};
	}

	private static PackedCostSession replaySessionWithLeafDelta(PackedCostingTrace cachedTrace, double leafDelta) {
		return new PackedCostSession() {
			private final FrontierStateArena arena = new FrontierStateArena(64L * 1024L);
			private final EvidenceStateRef state = arena.append(
					FrontierLayout.of("subject", "predicate", "object"), EvidenceStateSummary.exact(1.0d));
			private int eventId;

			@Override
			public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
				publish(PackedCostingPhase.LEAF, output);
			}

			@Override
			public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
				publish(PackedCostingPhase.PREFIX_EXTENSION, output);
			}

			@Override
			public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
				publish(PackedCostingPhase.OPERATOR, output);
			}

			@Override
			public void refineIntermediateJoin(PackedCostContext context, PackedCostEstimate output) {
				PackedCostingPhase phase = cachedTrace.phase(eventId + 1);
				assertTrue(phase == PackedCostingPhase.INTERMEDIATE_JOIN || phase == PackedCostingPhase.PHYSICAL_JOIN);
				publish(phase, output);
			}

			@Override
			public FrontierEvidenceBundle detachEvidence(int[] evidenceStateIds) {
				return arena.exportEvidence(evidenceStateIds);
			}

			@Override
			public void close() {
				arena.close();
			}

			private void publish(PackedCostingPhase expectedPhase, PackedCostEstimate output) {
				eventId++;
				assertEquals(expectedPhase, cachedTrace.phase(eventId));
				double work = cachedTrace.objectiveCost(eventId)
						+ (expectedPhase == PackedCostingPhase.LEAF ? leafDelta : 0.0d);
				output.setRows(cachedTrace.outputRows(eventId), work);
				output.setEvidenceStateId(state.stateId());
				output.setEvidenceGuarantee(state.summary().guarantee());
				output.setEvidenceDisposition(FrontierStateDisposition.COMPOSABLE_PAYLOAD);
			}
		};
	}

	private static Object controllerWithStableAudits(Constructor<?> constructor, Method observe, int count)
			throws Exception {
		Object controller = constructor.newInstance();
		for (int index = 0; index < count; index++) {
			observe.invoke(controller, 7L, index + 1L, index & 1, true, 0.0d);
		}
		return controller;
	}

	private static StatisticalFixtureResult assessConfidenceTier(double confidence) {
		final int populations = 64;
		final int populationSize = 4_096;
		final double contributionBound = 4.0d;
		int covered = 0;
		int harmfulPopulations = 0;
		int falseReuses = 0;
		int beneficialCertifications = 0;
		double regret = 0.0d;
		for (int population = 0; population < populations; population++) {
			double exhaustiveMeanDifference = (population & 1) == 0 ? 2.0d : -2.0d;
			SplittableRandom random = new SplittableRandom(0x9e3779b97f4a7c15L ^ population);
			FrontierPairedCostSequence sequence = new FrontierPairedCostSequence(
					confidence, 4, contributionBound);
			boolean populationCovered = true;
			FrontierPairedCostSequence.Snapshot snapshot = null;
			for (int observation = 1; observation <= populationSize; observation++) {
				double centeredNoise = random.nextDouble(-1.5d, 1.5d);
				sequence.observeAdjusted(0.0d, exhaustiveMeanDifference + centeredNoise, false);
				if (observation >= 64 && Integer.bitCount(observation) == 1) {
					snapshot = sequence.snapshot();
					populationCovered &= snapshot.lowerBound() <= exhaustiveMeanDifference
							&& snapshot.upperBound() >= exhaustiveMeanDifference;
				}
			}
			if (populationCovered) {
				covered++;
			}
			if (exhaustiveMeanDifference > 0.0d) {
				harmfulPopulations++;
				if (snapshot != null && snapshot.certifiesNegative()) {
					falseReuses++;
					regret += exhaustiveMeanDifference / 100.0d;
				}
			} else if (snapshot != null && snapshot.certifiesNegative()) {
				beneficialCertifications++;
			}
		}
		return new StatisticalFixtureResult(
				covered / (double) populations,
				falseReuses / (double) harmfulPopulations,
				regret / populations,
				beneficialCertifications);
	}

